/**
 * Exam-level vocabulary banks for browse/filter on the Categories page only.
 * Curated from well-known academic / exam lists — no invented spellings.
 * Not merged into the default DSE pack (recommend / learn / quiz stay DSE-only).
 */

import type { VocabWord } from './dseWords'

export type ExamLevel =
  | 'DSE'
  | 'IELTS'
  | 'TOEFL'
  | 'GRE'
  | 'A-Level'
  | 'SAT'
  | 'GCSE'
  | 'CET-4'
  | 'CET-6'

export type ExamLevelMeta = {
  id: ExamLevel
  label: string
  short: string
}

/** UI order for exam filters on 主题归类. */
export const EXAM_LEVELS: ExamLevelMeta[] = [
  { id: 'DSE', label: '香港 DSE', short: 'DSE' },
  { id: 'IELTS', label: '雅思 IELTS', short: 'IELTS' },
  { id: 'TOEFL', label: '托福 TOEFL', short: 'TOEFL' },
  { id: 'GRE', label: 'GRE', short: 'GRE' },
  { id: 'A-Level', label: '英国 A-Level', short: 'A-Level' },
  { id: 'SAT', label: 'SAT', short: 'SAT' },
  { id: 'GCSE', label: '英国 GCSE', short: 'GCSE' },
  { id: 'CET-4', label: '大学英语四级 CET-4', short: 'CET-4' },
  { id: 'CET-6', label: '大学英语六级 CET-6', short: 'CET-6' },
]

export function wordExams(w: VocabWord): ExamLevel[] {
  if (w.exams && w.exams.length > 0) return w.exams
  return ['DSE']
}

export function wordInExam(w: VocabWord, exam: ExamLevel | '全部'): boolean {
  if (exam === '全部') return true
  return wordExams(w).includes(exam)
}

