export function mergeCategoryBrowseWords(dsePackWords: VocabWord[]): VocabWord[] {
  const byId = new Map<string, VocabWord>()
  for (const w of dsePackWords) byId.set(w.id, w)
  for (const w of examExtraWords) {
    if (!byId.has(w.id)) byId.set(w.id, w)
  }
  return [...byId.values()]
}

export function countByExam(words: VocabWord[]): Record<ExamLevel, number> {
  const out = Object.fromEntries(EXAM_LEVELS.map((e) => [e.id, 0])) as Record<ExamLevel, number>
  for (const w of words) {
    for (const e of wordExams(w)) {
      if (e in out) out[e] += 1
    }
  }
  return out
}

